function demoMain(idx,label){
  var pages=[["img-no-alt",1],["low-contrast",2],["missing-label",1]];
  var p=pages[idx%pages.length];
  return "["+label+"] scanned page: "+p[1]+" "+p[0]+" violation(s) found (WCAG 2.1 AA)";
}

